import React, { useState, useMemo, useContext, useEffect } from 'react';
import { Upload, FileText, Search, AlertCircle, Loader2, Wallet, ArrowUpRight, ArrowDownRight, BadgeInfo } from 'lucide-react';
import '../styles/Airtel.css';
import '../styles/ParserPages.css';
import { WealthContext } from '../../context/wealthContext';
import { formatMoney } from '../../utils/money';

const Airtel = () => {
    const [file, setFile] = useState(null);
    const [transactions, setTransactions] = useState(null);
    const [summary, setSummary] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [searchTerm, setSearchTerm] = useState('');
    const { saveWalletSnapshot, wealthState } = useContext(WealthContext);

    // Hydrate cached parse after refresh.
    useEffect(() => {
        if (transactions && transactions.length > 0) return;
        const cached = wealthState?.wallets?.airtel;
        if (!cached?.transactions?.length) return;
        setTransactions(cached.transactions);
        setSummary(cached.summary || null);
    }, [transactions, wealthState]);

    // Rehydrate from DB if local cache is empty.
    useEffect(() => {
        const load = async () => {
            if (transactions && transactions.length > 0) return;
            try {
                const res = await fetch('http://localhost:4000/api/statements/latest?provider=airtel', {
                    method: 'GET',
                    headers: { 'Accept': 'application/json' },
                    credentials: 'include',
                });
                const data = await res.json();
                if (!data?.success || !data?.transactions?.length) return;
                setTransactions(data.transactions);
                setSummary(data.summary || null);
                saveWalletSnapshot('airtel', {
                    provider: 'Airtel Money',
                    label: 'Airtel Wallet',
                    worth: data.summary?.closingBalance || '0.00',
                    balance: data.summary?.closingBalance || '0.00',
                    summary: data.summary || null,
                    transactions: data.transactions || [],
                    customerName: data.summary?.customerName || '',
                    statementPeriod: data.summary?.statementPeriod || '',
                    requestDate: data.summary?.requestDate || '',
                });
            } catch {
                // ignore
            }
        };
        load();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const handleUpload = async (e) => {
        e.preventDefault();
        if (!file) return;

        setLoading(true);
        setError(null);
        setSummary(null);
        const formData = new FormData();
        formData.append('statement', file);

        try {
            const response = await fetch('http://localhost:5000/api/parse/airtel', {
                method: 'POST',
                body: formData,
            });
            const result = await response.json();

            if (result.success) {
                setTransactions(result.transactions);
                setSummary(result.summary || null);
                saveWalletSnapshot('airtel', {
                    provider: 'Airtel Money',
                    label: 'Airtel Wallet',
                    worth: result.summary?.closingBalance || '0.00',
                    balance: result.summary?.closingBalance || '0.00',
                    summary: result.summary || null,
                    transactions: result.transactions || [],
                    customerName: result.summary?.customerName || '',
                    statementPeriod: result.summary?.statementPeriod || '',
                    requestDate: result.summary?.requestDate || '',
                });

                try {
                    const saveRes = await fetch('http://localhost:4000/api/statements', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
                        credentials: 'include',
                        body: JSON.stringify({
                            provider: 'airtel',
                            summary: result.summary || {},
                            transactions: result.transactions || [],
                            meta: { source: 'pdf-upload' },
                        })
                    });
                    if (!saveRes.ok) {
                        const errBody = await saveRes.text();
                        console.error('Failed to save airtel statement:', saveRes.status, errBody);
                    }
                } catch (err) {
                    console.error('Failed to save airtel statement:', err);
                }
            } else {
                setError(result.error || 'Failed to parse Airtel statement.');
            }
        } catch (err) {
            setError('Cannot connect to the backend server. Ensure it is running on port 5000.');
        } finally {
            setLoading(false);
        }
    };

    const filteredData = useMemo(() => {
        if (!transactions) return [];
        return transactions.filter(tx =>
            tx.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
            tx.transactionId.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [transactions, searchTerm]);

    const worthValue = summary?.closingBalance || '0.00';

    return (
        <div className="parser-page airtel-wrapper">
            {/* Header Section */}
            <header className="parser-page-header airtel-header">
                <div className="airtel-icon-box"><FileText size={24} /></div>
                <div className="parser-page-heading">
                    <span className="parser-page-eyebrow">MOBILE MONEY · STATEMENTS</span>
                    <h1>Airtel Money statement</h1>
                    <p>Review wallet activity and balances from your Airtel Money PDF.</p>
                </div>
            </header>

            {/* Upload Section */}
            <section className="parser-upload-card airtel-card" aria-labelledby="airtel-upload-title">
                <div className="parser-upload-heading">
                    <div>
                        <h2 id="airtel-upload-title">Upload a statement</h2>
                        <p>Select a PDF statement to prepare your transaction overview.</p>
                    </div>
                    <span className="parser-file-type">PDF statement</span>
                </div>
                <form onSubmit={handleUpload} className="airtel-upload-grid">
                    <div className="airtel-input-group">
                        <label htmlFor="airtel-statement-file">Statement PDF</label>
                        <input
                            id="airtel-statement-file"
                            type="file"
                            accept=".pdf"
                            onChange={(e) => setFile(e.target.files[0])}
                            className="airtel-file-input"
                        />
                    </div>
                    <button type="submit" disabled={loading || !file} className="airtel-parse-btn">
                        {loading ? <Loader2 className="airtel-spin" size={20} /> : <Upload size={20} />}
                        {loading ? 'Processing...' : 'Analyze PDF'}
                    </button>
                </form>
                {error && <div className="airtel-error-msg"><AlertCircle size={18} /> {error}</div>}
            </section>

            {/* Results Section */}
            {transactions && (
                <div className="airtel-table-container">
                    {summary && (
                        <div className="airtel-summary-panel">
                            <div className="airtel-summary-main">
                                <div className="airtel-summary-pill">
                                    <Wallet size={16} />
                                    Airtel Wallet Worth
                                </div>
                                <div className="airtel-summary-value">Ksh {formatMoney(worthValue)}</div>
                                <div className="airtel-summary-meta">
                                    {summary.customerName ? <span>{summary.customerName}</span> : null}
                                    {summary.statementPeriod ? <span>{summary.statementPeriod}</span> : null}
                                </div>
                            </div>

                            <div className="airtel-summary-grid">
                                <div className="airtel-summary-card">
                                    <ArrowUpRight size={16} />
                                    <span>Total Credit</span>
                                    <strong>Ksh {formatMoney(summary.totalCredit)}</strong>
                                </div>
                                <div className="airtel-summary-card">
                                    <ArrowDownRight size={16} />
                                    <span>Total Debit</span>
                                    <strong>Ksh {formatMoney(summary.totalDebit)}</strong>
                                </div>
                                <div className="airtel-summary-card">
                                    <BadgeInfo size={16} />
                                    <span>Closing Balance</span>
                                    <strong>Ksh {formatMoney(summary.closingBalance)}</strong>
                                </div>
                            </div>
                        </div>
                    )}

                    <div className="airtel-table-header">
                        <div className="airtel-title-area">
                            <h3>Detailed Transactions</h3>
                            <p className="airtel-count-subtext">Found {filteredData.length} records</p>
                        </div>

                        <div className="airtel-search-box">
                            <Search size={18} className="search-icon" />
                            <input
                                type="text"
                                placeholder="Search description or transaction ID..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                    </div>

                    <div className="airtel-scroll-area">
                        <table className="airtel-statement-table">
                            <thead>
                                <tr>
                                    <th>Transaction ID</th>
                                    <th>Transaction Date</th>
                                    <th>Description</th>
                                    <th>Status</th>
                                    <th className="airtel-text-right">Credit</th>
                                    <th className="airtel-text-right">Debit</th>
                                    <th className="airtel-text-right">Balance</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredData.map((tx, idx) => (
                                    <tr key={idx} className="airtel-row-hover">
                                        <td data-label="Transaction ID" className="airtel-tx-id-cell">{tx.transactionId}</td>
                                        <td data-label="Date" className="airtel-date-cell">{tx.transactionDate}</td>
                                        <td data-label="Description" className="airtel-details-cell">
                                            <div className="airtel-tx-desc">{tx.description}</div>
                                        </td>
                                        <td data-label="Status">
                                            <span className={`airtel-status-badge ${tx.status.toLowerCase().includes('successful') ? 'successful' : ''}`}>
                                                {tx.status}
                                            </span>
                                        </td>
                                        <td data-label="Credit" className="airtel-text-right airtel-amt-in">
                                            {tx.credit !== "0.00" ? `+Ksh ${tx.credit}` : '—'}
                                        </td>
                                        <td data-label="Debit" className="airtel-text-right airtel-amt-out">
                                            {tx.debit !== "0.00" ? `-Ksh ${tx.debit}` : '—'}
                                        </td>
                                        <td data-label="Balance" className="airtel-text-right airtel-balance-cell">Ksh {formatMoney(tx.balance)}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Airtel;
